	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := solveWidths(columns, tt.width, []int{20, 20})
			if !slices.Equal(got, tt.want) {
				t.Errorf("widths at %d = %v, want %v", tt.width, got, tt.want)
			}
		})
	}
}

