// Setting the flag where it cannot act (no Optional) never changes a layout.
func TestFlagWithoutOptionalChangesNothingAtAnyWidth(t *testing.T) {
	compared := 0
	for name, columns := range allLayouts() {
		flagged := slices.Clone(columns)
		for i := range flagged {
